from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Test valid
    try:
        ServerSentEvent(id="123", event="update", data="hello")
        print("Valid SSE passed")
    except ValidationError as e:
        print(f"Valid SSE failed: {e}")

    # Test newline in id
    try:
        ServerSentEvent(id="123\n", event="update", data="hello")
        print("Newline in id failed to raise")
    except ValidationError:
        print("Newline in id correctly raised")

    # Test newline in event
    try:
        ServerSentEvent(id="123", event="up\ndate", data="hello")
        print("Newline in event failed to raise")
    except ValidationError:
        print("Newline in event correctly raised")

    # Test null in id
    try:
        ServerSentEvent(id="123\0", event="update", data="hello")
        print("Null in id failed to raise")
    except ValidationError:
        print("Null in id correctly raised")

    # Test null in event
    try:
        ServerSentEvent(id="123", event="up\0date", data="hello")
        print("Null in event failed to raise")
    except ValidationError:
        print("Null in event correctly raised")

if __name__ == "__main__":
    test_sse_validation()

